from typing import List

class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        # Helper to perform DFS, returns a set of expanded strings for s[l:r+1]
        def dfs(l, r):
            # Holds top-level comma-separated expressions
            res = set()
            bal = 0
            last = l
            found_comma = False
            for i in range(l, r + 1):
                if expression[i] == '{':
                    bal += 1
                elif expression[i] == '}':
                    bal -= 1
                elif expression[i] == ',' and bal == 0:
                    res |= dfs(last, i - 1)
                    last = i + 1
                    found_comma = True
            if found_comma:
                res |= dfs(last, r)
                return res
            # No commas outside braces: parse as concatenation
            ans = ['']
            i = l
            while i <= r:
                if expression[i] == '{':
                    # Find matching }
                    j, cnt = i, 0
                    while j <= r:
                        if expression[j] == '{':
                            cnt += 1
                        elif expression[j] == '}':
                            cnt -= 1
                        if cnt == 0:
                            break
                        j += 1
                    sub = dfs(i + 1, j - 1)
                    ans = [a + b for a in ans for b in sub]
                    i = j + 1
                else:
                    # Read a sequence of letters until next brace/comma
                    j = i
                    while j <= r and expression[j].isalpha():
                        j += 1
                    part = expression[i:j]
                    ans = [a + part for a in ans]
                    i = j
            return set(ans)

        return sorted(dfs(0, len(expression) - 1))
